package library_test

import (
	"bytes"
	"fmt"
	"go/format"
	"io/fs"
	"maps"
	"path"
	"slices"
	"strings"
	"testing"

	"go.dokimi.dev/assert"
	"go.dokimi.dev/assert/golden"

	"go.dokimi.dev/eidos/lang/treesitter"
	tsgrammar "go.dokimi.dev/eidos/lang/treesitter/typescript"
	"go.dokimi.dev/eidos/lang/typescript/frontend/library"
)

// The generated file of the index, the module file of the release, the
// keyword of a declare global block, and the separator of the names of a
// dotted namespace.
const (
	indexFile     = "index.gen.go"
	iteratorFile  = "lib.es2025.iterator.d.ts"
	globalKeyword = "global"
	dottedSep     = "."
)

// indexHeader opens the generated file of the index: the licence header,
// the mark of a generated file, the package clause and the documentation
// of the index.
const indexHeader = `// Copyright Dokimasia B.V. 2026
// SPDX-License-Identifier: Apache-2.0

// Code generated by TestIndex with -update. DO NOT EDIT.

package library

// Index is the entry of each file of [Files] by the name of the file, as
// lib.es5.d.ts. A file without a declaration, such as a file of reference
// directives alone, has an entry without statements. Any number of
// goroutines may read the map, and no caller writes it.
var Index = map[string]Entry{
`

// The kinds and the field of the grammar of TypeScript that the derivation
// of the index reads.
var (
	importStatement          = tsgrammar.TypeScript.Kind("import_statement")
	exportStatement          = tsgrammar.TypeScript.Kind("export_statement")
	ambientDeclaration       = tsgrammar.TypeScript.Kind("ambient_declaration")
	expressionStatement      = tsgrammar.TypeScript.Kind("expression_statement")
	statementBlock           = tsgrammar.TypeScript.Kind("statement_block")
	interfaceDeclaration     = tsgrammar.TypeScript.Kind("interface_declaration")
	typeAliasDeclaration     = tsgrammar.TypeScript.Kind("type_alias_declaration")
	functionSignature        = tsgrammar.TypeScript.Kind("function_signature")
	classDeclaration         = tsgrammar.TypeScript.Kind("class_declaration")
	abstractClassDeclaration = tsgrammar.TypeScript.Kind("abstract_class_declaration")
	variableDeclaration      = tsgrammar.TypeScript.Kind("variable_declaration")
	lexicalDeclaration       = tsgrammar.TypeScript.Kind("lexical_declaration")
	internalModule           = tsgrammar.TypeScript.Kind("internal_module")
	moduleDeclaration        = tsgrammar.TypeScript.Kind("module")
	nameField                = tsgrammar.TypeScript.Field("name")
)

// wrapped are the kinds of the declarations that a declare statement or an
// expression statement wraps.
var wrapped = []treesitter.Kind{
	interfaceDeclaration, typeAliasDeclaration, functionSignature, classDeclaration, abstractClassDeclaration,
	variableDeclaration, lexicalDeclaration, internalModule, moduleDeclaration,
}

// The index is the statements of the global names of each file of the
// release as the grammar of TypeScript reads them, so a load slices a file
// without a parse. A run with -update writes the index from the files.
func TestIndex(t *testing.T) {
	t.Parallel()

	index := derived(t)

	t.Run("Index", func(t *testing.T) {
		t.Parallel()

		t.Run("has the statements of the global names of each file of the release", func(t *testing.T) {
			t.Parallel()

			assert.Equal(t, library.Index, index, "the index has what the grammar reads from each file")
		})

		t.Run("has the source that the index of the files renders", func(t *testing.T) {
			t.Parallel()

			golden.MatchAt(t, indexFile, render(t, index), golden.ShouldUpdate())
		})

		t.Run("has a statement over the whole module file for each name of its global block", func(t *testing.T) {
			t.Parallel()

			src, err := fs.ReadFile(library.Files, path.Join(library.Dir, iteratorFile))
			assert.NoError(t, err, "the embed reads the module file")
			assert.Equal(t, library.Index[iteratorFile], library.Entry{Module: true, Statements: []library.Statement{
				{Name: "IteratorObject", End: len(src)},
				{Name: "IteratorConstructor", End: len(src)},
				{Name: "Iterator", End: len(src)},
			}}, "the global names of the module file, each over the whole file")
		})
	})
}

// derived returns the index of the files of [library.Files] as the grammar
// of TypeScript reads them.
func derived(t *testing.T) map[string]library.Entry {
	t.Helper()

	entries, err := fs.ReadDir(library.Files, library.Dir)
	assert.NoError(t, err, "the embed lists its directory")
	out := make(map[string]library.Entry, len(entries))
	for _, e := range entries {
		out[e.Name()] = entryOf(t, e.Name())
	}
	return out
}

// entryOf returns the entry of one file of the library: the statements of
// a script, and the global names of a module file, which has a top-level
// import or export.
func entryOf(t *testing.T, file string) library.Entry {
	t.Helper()

	src, err := fs.ReadFile(library.Files, path.Join(library.Dir, file))
	assert.NoError(t, err, "the embed reads "+file)
	tree, err := tsgrammar.TypeScript.Parse(t.Context(), file, src)
	assert.NoError(t, err, "the grammar parses "+file)
	defer tree.Close()
	root := tree.Root()
	if root.FirstOf(importStatement, exportStatement).IsZero() {
		return library.Entry{Statements: scriptStatements(t, root, src)}
	}
	return library.Entry{Module: true, Statements: globalStatements(root, len(src))}
}

// scriptStatements returns the statements of a script, one for each
// top-level declaration. A statement starts where the statement before it
// ends, and ends at the line break that ends its last line.
func scriptStatements(t *testing.T, root treesitter.Node, src []byte) []library.Statement {
	t.Helper()

	lines := []int{0}
	for i, c := range src {
		if c == '\n' {
			lines = append(lines, i+1)
		}
	}
	var out []library.Statement
	start := 0
	for stmt := range root.Content() {
		at, last := stmt.Pos(), stmt.End()
		names := declared(stmt)
		assert.Length(t, names, 1, fmt.Sprintf("the statement at %s declares one name", at))
		assert.InRange(t, lines[at.Line-1]+at.Col-1, float64(start), float64(len(src)),
			fmt.Sprintf("the statement at %s starts after the line of the statement before it", at))
		end := lines[last.Line-1] + last.Col - 1
		if eol := bytes.IndexByte(src[end:], '\n'); eol >= 0 {
			end += eol
		} else {
			end = len(src)
		}
		out = append(out, library.Statement{Name: names[0], Start: start, End: end})
		start = end
	}
	return out
}

// globalStatements returns the statements of a module file: one for each
// name that its declare global blocks declare, in the order of the file,
// each over the whole file of size bytes.
func globalStatements(root treesitter.Node, size int) []library.Statement {
	var out []library.Statement
	for stmt := range root.Content() {
		if stmt.Kind() != ambientDeclaration || !stmt.HasToken(globalKeyword) {
			continue
		}
		for decl := range stmt.FirstOf(statementBlock).Content() {
			for _, name := range declared(decl) {
				if !slices.ContainsFunc(out, func(s library.Statement) bool { return s.Name == name }) {
					out = append(out, library.Statement{Name: name, End: size})
				}
			}
		}
	}
	return out
}

// declared returns the names that one statement declares: the name of a
// declaration, the name of each variable of a statement of variables, and
// the first name of a namespace. A declare statement and an expression
// statement declare what the statement inside them declares.
func declared(stmt treesitter.Node) []string {
	switch stmt.Kind() {
	case ambientDeclaration, expressionStatement:
		return declared(stmt.FirstOf(wrapped...))
	case variableDeclaration, lexicalDeclaration:
		var names []string
		for declarator := range stmt.Content() {
			names = append(names, declarator.Child(nameField).Text())
		}
		return names
	case internalModule, moduleDeclaration:
		head, _, _ := strings.Cut(stmt.Child(nameField).Text(), dottedSep)
		return []string{head}
	case interfaceDeclaration, typeAliasDeclaration, functionSignature, classDeclaration, abstractClassDeclaration:
		return []string{stmt.Child(nameField).Text()}
	}
	return nil
}

// render returns the Go source of an index: the header, then the entry of
// each file in the order of the names of the files, with each statement on
// a line of its own.
func render(t *testing.T, index map[string]library.Entry) []byte {
	t.Helper()

	var b strings.Builder
	b.WriteString(indexHeader)
	for _, file := range slices.Sorted(maps.Keys(index)) {
		e := index[file]
		if len(e.Statements) == 0 {
			fmt.Fprintf(&b, "\t%q: {},\n", file)
			continue
		}
		module := ""
		if e.Module {
			module = "Module: true, "
		}
		fmt.Fprintf(&b, "\t%q: {%sStatements: []Statement{\n", file, module)
		for _, s := range e.Statements {
			fmt.Fprintf(&b, "\t\t{Name: %q, Start: %d, End: %d},\n", s.Name, s.Start, s.End)
		}
		b.WriteString("\t}},\n")
	}
	b.WriteString("}\n")
	src, err := format.Source([]byte(b.String()))
	assert.NoError(t, err, "the index renders as Go source")
	return src
}
